#!/usr/bin/env bash
# post_api_changelog_comment.sh — Create or update the API changelog PR comment.
#
# Env contract (fail-fast if missing):
#   GITHUB_TOKEN       — GitHub API token with pull-requests:write scope
#   GITHUB_REPOSITORY  — owner/repo (e.g. "kv-shepherd/shepherd")
#   PR_NUMBER          — pull request number
#
# Expects /tmp/api-changelog.md to exist (generated by `make api-changelog`).
# Equivalent to the inline script previously in api-contract-validation.yml L95-L129.

set -euo pipefail

: "${GITHUB_TOKEN:?GITHUB_TOKEN is required}"
: "${GITHUB_REPOSITORY:?GITHUB_REPOSITORY is required}"
: "${PR_NUMBER:?PR_NUMBER is required}"

CHANGELOG_FILE="${CHANGELOG_FILE:-/tmp/api-changelog.md}"

if [ ! -f "$CHANGELOG_FILE" ]; then
  if [ "${ALLOW_MISSING_CHANGELOG:-0}" = "1" ]; then
    echo "No changelog file at ${CHANGELOG_FILE}; skipping (ALLOW_MISSING_CHANGELOG=1)."
    exit 0
  fi
  echo "ERROR: No changelog file at ${CHANGELOG_FILE}; failing to prevent silent skip."
  echo "  Set ALLOW_MISSING_CHANGELOG=1 to explicitly allow missing changelog."
  exit 1
fi

MARKER="<!-- api-contract-changelog -->"
COMMENT_BODY="$(mktemp)"
{
  echo "${MARKER}"
  echo "## API Changelog"
  echo
  cat "${CHANGELOG_FILE}"
} > "${COMMENT_BODY}"

COMMENTS_API="https://api.github.com/repos/${GITHUB_REPOSITORY}/issues/${PR_NUMBER}/comments"

EXISTING_ID="$(curl -fsSL \
  -H "Authorization: Bearer ${GITHUB_TOKEN}" \
  -H "Accept: application/vnd.github+json" \
  "${COMMENTS_API}" | jq -r --arg marker "${MARKER}" '.[] | select(.body | contains($marker)) | .id' | head -n1)"

JSON_PAYLOAD="$(jq -Rs '{body: .}' < "${COMMENT_BODY}")"

if [ -n "${EXISTING_ID}" ]; then
  curl -fsSL -X PATCH \
    -H "Authorization: Bearer ${GITHUB_TOKEN}" \
    -H "Accept: application/vnd.github+json" \
    -H "Content-Type: application/json" \
    "https://api.github.com/repos/${GITHUB_REPOSITORY}/issues/comments/${EXISTING_ID}" \
    -d "${JSON_PAYLOAD}" > /dev/null
  echo "✅ Updated existing API changelog comment (${EXISTING_ID})"
else
  curl -fsSL -X POST \
    -H "Authorization: Bearer ${GITHUB_TOKEN}" \
    -H "Accept: application/vnd.github+json" \
    -H "Content-Type: application/json" \
    "${COMMENTS_API}" \
    -d "${JSON_PAYLOAD}" > /dev/null
  echo "✅ Created new API changelog comment"
fi

rm -f "${COMMENT_BODY}"
